return ['project-id-version'=>'Lingua Forge 2.1.0','report-msgid-bugs-to'=>'https://wordpress.org/support/plugin/lingua-forge','last-translator'=>'admin','language-team'=>'Indonesian','mime-version'=>'1.0','content-type'=>'text/plain; charset=UTF-8','content-transfer-encoding'=>'8bit','pot-creation-date'=>'2026-06-01T15:14:22+00:00','po-revision-date'=>'2026-06-01 17:57+0000','x-generator'=>'Loco https://localise.biz/','x-domain'=>'lingua-forge','language'=>'id_ID','plural-forms'=>'nplurals=1; plural=0;','x-loco-version'=>'2.8.5; wp-7.0; php-8.3.31','messages'=>['Lingua Forge'=>'Lingua Forge','https://github.com/leotiger/lingua-forge'=>'https://github.com/leotiger/lingua-forge','Multilingual routing, SEO meta tags, and AI content tools for WordPress. Combines language detection, URL routing, hreflang, meta descriptions, and AI-powered excerpt, meta, and translation features.'=>'Routing multibahasa, meta tag SEO, dan alat konten AI untuk WordPress. Menggabungkan deteksi bahasa, routing URL, hreflang, deskripsi meta, dan fitur kutipan, meta, serta terjemahan yang didukung AI.','Uli Hake'=>'Uli Hake','https://lingua-forge.com'=>'https://lingua-forge.com','Translate'=>'Terjemahkan','Lingua Forge — Quick Translate'=>'Lingua Forge — Terjemahan Cepat','Informative'=>' Informatif','Persuasive'=>' Persuasif','Storytelling'=>' Bercerita','Technical'=>' Teknis','Conversational'=>' Percakapan','Permission denied.'=>' Izin ditolak.','Cannot determine target language from slug.'=>' Tidak dapat menentukan bahasa target dari slug.','Invalid post type.'=>' Jenis posting tidak valid.','Invalid or primary language.'=>' Bahasa tidak valid atau utama.','Template not found or not stored in the database.'=>' Template tidak ditemukan atau tidak disimpan dalam database.','Template has no content.'=>' Template tidak memiliki konten.','No internal links found to update.'=>' Tidak ditemukan tautan internal untuk diperbarui.','%d link updated.'=>'%d tautan diperbarui.' . "\0" . '','No language-specific template parts found to map.'=>' Tidak ditemukan bagian template khusus bahasa untuk dipetakan.','No template part references needed updating.'=>' Tidak diperlukan pembaruan referensi bagian template.','%d part reference updated.'=>'%d referensi bagian diperbarui.' . "\0" . '','Invalid language.'=>'Bahasa tidak valid.','Template part not found or not stored in the database.'=>' Bagian template tidak ditemukan atau tidak disimpan dalam database.','Template part has no content.'=>' Bagian template tidak memiliki konten.','No navigation references needed updating.'=>' Tidak diperlukan pembaruan referensi navigasi.','%d navigation reference updated.'=>'%d referensi navigasi diperbarui.' . "\0" . '','No AI provider configured.'=>' Penyedia AI tidak dikonfigurasi.','Missing pattern name or language.'=>' Nama pola atau bahasa yang hilang.','Pattern not found.'=>' Pola tidak ditemukan.','Pattern has no content to translate.'=>' Pola tidak memiliki konten untuk diterjemahkan.','AI provider returned an empty response.'=>' Penyedia AI mengembalikan respons kosong.','Pattern translated and saved. Copy the content into your CPT post via the block editor Pattern inserter or use it as a starting point for a Reusable Block.'=>' Pola diterjemahkan dan disimpan. Salin konten ke posting CPT Anda melalui inserter pola editor blok atau gunakan sebagai titik awal untuk Blok yang Dapat Digunakan Kembali.','Invalid template type.'=>' Jenis template tidak valid.','Template "%s" already exists.'=>'"%s" sudah ada.','"%s" created.'=>'"%s" dibuat.','Invalid template part.'=>' Bagian template tidak valid.','Template part "%s" already exists.'=>' Bagian template "%s" sudah ada.','"%1$s" created. %2$d template updated.'=>'"%1$s" dibuat. %2$d template diperbarui.' . "\0" . '','Page'=>'Halaman','Single'=>' Tunggal','Search'=>' Cari','Search Results'=>' Hasil Pencarian','Archive'=>' Arsip','Front Page'=>' Halaman Depan','Single: %s'=>' Tunggal: %s','Single %s'=>' %s Tunggal','Archive: %s'=>' Arsip: %s','%s Archive'=>' Arsip %s','No source content found to translate.'=>'Tidak ada konten sumber yang ditemukan untuk diterjemahkan.','Translated. Review in the Site Editor — internal links, navigation URLs, and template slugs are not updated automatically.'=>'Diterjemahkan. Tinjau di Editor Situs — tautan internal, URL navigasi, dan slug template tidak diperbarui secara otomatis.','Navigation not found.'=>'Navigasi tidak ditemukan.','Navigation has no content to translate.'=>'Navigasi tidak memiliki konten untuk diterjemahkan.','"%1$s %2$s" saved.'=>'"%1$s %2$s" disimpan.','Translate page…'=>'Terjemahkan halaman…','Generate content…'=>'Hasilkan konten…','AI Behaviour Preset'=>'Preset Perilaku AI','Custom'=>'Kustom','Global default (%s)'=>'Default global (%s)','Overrides the AI preset for Translation and Content Generation on this page. Site-wide custom prompt instructions (Settings → Behavior) are always appended to every request regardless of this selection.'=>'Mengganti preset AI untuk Terjemahan dan Pembuatan Konten di halaman ini. Instruksi prompt kustom di seluruh situs (Pengaturan → Perilaku) selalu ditambahkan ke setiap permintaan terlepas dari pilihan ini.','Overrides the AI preset for Translation and Content Generation on this page. All other features always use the global preset.'=>'Mengganti preset AI untuk Terjemahan dan Pembuatan Konten di halaman ini. Semua fitur lainnya selalu menggunakan preset global.','Close'=>'Tutup','Translate missing'=>'Terjemahan hilang','From'=>'Dari','Retranslate'=>'Terjemahkan ulang','Translating…'=>'Sedang menerjemahkan…','Retranslating…'=>'Sedang menerjemahkan ulang…','✓ Done'=>'✓ Selesai','Error'=>'Kesalahan','Navigation posts are translated via the Router tab, not this button.'=>'Pos navigasi diterjemahkan melalui tab Router, bukan tombol ini.','Creating translations for post type "%s" requires an active integration. Please ensure the required integration is installed and active.'=>'Membuat terjemahan untuk tipe pos "%s" memerlukan integrasi aktif. Pastikan integrasi yang diperlukan terpasang dan aktif.','No %s version found in this translation group.'=>'Tidak ditemukan versi %s dalam grup terjemahan ini.','AI Usage'=>'Penggunaan AI','Today'=>'Hari ini','Last 7 days'=>'7 hari terakhir','Last 30 days'=>'30 hari terakhir','All time'=>'Semua waktu','Token consumption rolled up by feature, provider, and model. Recorded on every successful AI call; Test Connection pings are deliberately excluded so they don\'t skew the totals. The underlying table aggregates daily — pick a window below to view it.'=>'Penggunaan token yang dikumpulkan berdasarkan fitur, penyedia, dan model. Dicatat pada setiap panggilan AI yang berhasil; ping Uji Koneksi secara sengaja dikecualikan agar tidak mempengaruhi total. Tabel dasar mengagregasi harian — pilih jendela di bawah untuk melihatnya.','No AI usage recorded yet. Once an editor runs a translation, generates a meta description, or uses any other AI feature, totals will appear here.'=>'Penggunaan AI belum tercatat. Setelah editor menjalankan terjemahan, menghasilkan deskripsi meta, atau menggunakan fitur AI lainnya, total akan muncul di sini.','No AI usage recorded in the selected window (%s). Pick a wider range above.'=>'Penggunaan AI tidak tercatat dalam jendela yang dipilih (%s). Pilih rentang yang lebih luas di atas.','Feature'=>'Fitur','Provider'=>'Penyedia','Model'=>'Model','Requests'=>'Permintaan','Input tokens'=>'Token input','Output tokens'=>'Token output','Total tokens'=>'Total token','Total'=>'Total','API Keys'=>'Kunci API','Keys are encrypted with AES-256-CBC before being stored in the WordPress database. The encryption secret is derived from your WordPress auth salts (wp-config.php), so plaintext keys never touch the database.'=>'Kunci API dienkripsi dengan AES-256-CBC sebelum disimpan di basis data WordPress. Rahasia enkripsi diambil dari garam otentikasi WordPress Anda (wp-config.php), sehingga kunci teks biasa tidak pernah menyentuh basis data.','API Key'=>'Kunci API','Paste your API key…'=>'Tempelkan kunci API Anda…','✓ Configured'=>'✓ Dikonfigurasi','✗ Not configured'=>'✗ Tidak dikonfigurasi','Test connection'=>'Uji koneksi','Leave blank to keep the existing key. Enter a new value to replace it.'=>'Biarkan kosong untuk mempertahankan kunci yang ada. Masukkan nilai baru untuk menggantinya.','Remove stored key'=>'Hapus kunci yang disimpan','This key is currently supplied by a server %s and cannot be removed here. Enter a new key above to override it with a database value.'=>'Kunci ini saat ini disediakan oleh server %s dan tidak dapat dihapus di sini. Masukkan kunci baru di atas untuk menggantinya dengan nilai dari basis data.','environment variable'=>'variabel lingkungan','PHP constant'=>'Konstanta PHP','Alternative (server-side):'=>'Alternatif (sisi server):','You can also define keys as constants or environment variables (e.g. in wp-config.php). Those sources are used automatically as a fallback when no database key is stored.'=>'Anda juga dapat mendefinisikan kunci sebagai konstanta atau variabel lingkungan (misalnya di wp-config.php). Sumber-sumber tersebut digunakan secara otomatis sebagai cadangan jika tidak ada kunci database yang disimpan.','To use a custom encryption secret (instead of the derived wp_salt value), add this to wp-config.php:'=>'Untuk menggunakan rahasia enkripsi khusus (alih-alih nilai wp_salt yang diambil dari), tambahkan ini ke wp-config.php:','Unknown provider.'=>'Penyedia tidak dikenal.','No API key configured for this provider.'=>'Tidak ada kunci API yang dikonfigurasi untuk penyedia ini.','Could not instantiate the provider.'=>'Tidak dapat menginisialisasi penyedia.','Provider returned no text. Check the WordPress error log for the detailed failure reason.'=>'Penyedia tidak mengembalikan teks. Periksa log kesalahan WordPress untuk alasan kegagalan secara rinci.','Behavior'=>'Perilaku','Block Editor'=>'Editor Blok','Lingua Forge restricts two Gutenberg features by default to keep editorial behavior consistent across languages. Opt in here when you need full Gutenberg / FSE capabilities.'=>'Lingua Forge membatasi dua fitur Gutenberg secara default untuk menjaga konsistensi perilaku editorial di berbagai bahasa. Pilih di sini jika Anda membutuhkan kemampuan Gutenberg / FSE penuh.','Block locking'=>'Mengunci blok','Allow editors to lock individual blocks'=>'Izinkan editor mengunci blok individual','Re-enables Gutenberg\'s canLockBlocks. Useful for editorial templates that need to prevent contributors from moving or deleting specific blocks.'=>'Mengaktifkan kembali canLockBlocks Gutenberg. Berguna untuk template editorial yang perlu mencegah kontributor memindahkan atau menghapus blok tertentu.','Template mode'=>'Mode template','Allow Gutenberg template-editing mode on post screens'=>'Izinkan mode pengeditan template Gutenberg di layar posting','Re-enables supportsTemplateMode. Core to Full-Site-Editing workflows where post-level template overrides are intentional.'=>'Mengaktifkan kembali supportsTemplateMode. Inti dari alur kerja Pengeditan Seluruh Situs di mana override template tingkat posting adalah sengaja.','Compliance Preset'=>'Preset Kepatuhan','Strict-preservation mode for legal, regulatory, medical, or technical content. When on, every AI feature uses a low sampling temperature and appends the addendum below to its system prompt — terminology, article numbers, units, brand names, and regulatory language are preserved verbatim rather than paraphrased.'=>'Mode pelestarian ketat untuk konten hukum, regulasi, medis, atau teknis. Saat aktif, setiap fitur AI menggunakan suhu sampling rendah dan menambahkan addendum di bawah ke prompt sistemnya — terminologi, nomor artikel, satuan, nama merek, dan bahasa regulasi dipertahankan secara verbatim daripada diparafrasekan.','Global AI preset'=>'Preset AI global','T=%s'=>'T=%s','T=0.2–0.6, per feature'=>'T=0.2–0.6, per fitur','Sets the default AI behaviour for all features site-wide. Individual posts can override this for Translation and Content Generation via the Lingua Forge meta box.'=>'Mengatur perilaku AI default untuk semua fitur di seluruh situs. Postingan individual dapat mengesampinginya untuk Terjemahan dan Pembuatan Konten melalui kotak meta Lingua Forge.','Standard uses each feature\'s own tuned temperature: Translation T=0.2 (precise), Quick Translate T=0.4, Content Generator T=0.6 (creative). The other presets apply a single fixed temperature across all features.'=>'Standar menggunakan suhu yang disesuaikan untuk setiap fitur: Terjemahan T=0.2 (tepat), Terjemahan Cepat T=0.4, Pembuat Konten T=0.6 (kreatif). Preset lainnya menerapkan suhu tetap tunggal di semua fitur.','Technical / Scientific instructions'=>'Instruksi Teknis / Ilmiah','Legal / Compliance instructions'=>'Instruksi Hukum / Kepatuhan','Creative / Marketing instructions'=>'Instruksi Kreatif / Pemasaran','Leave blank to use the built-in default. Clearing a saved override restores the default on next save.'=>'Biarkan kosong untuk menggunakan default bawaan. Menghapus override yang disimpan akan mengembalikan ke default saat penyimpanan berikutnya.','View built-in default'=>'Lihat default bawaan','Translation Memory'=>'Memori Terjemahan','Cache translated equivalents at the block level so reusable content (shared footers, sidebars, accordions, boilerplate-heavy legal sections) does not pay an API call every time. When enabled, the translation flow parses each post into blocks, looks each block up in the cache, and sends only uncached blocks to the AI in a single batched request. Glossary edits and Compliance preset changes automatically invalidate affected cached translations. View statistics and clear the cache under Maintenance.'=>'Cache padanan terjemahan di tingkat blok agar konten yang dapat digunakan kembali (footer bersama, sidebar, akordeon, bagian hukum yang banyak boilerplate) tidak memanggil API setiap kali. Saat diaktifkan, alur terjemahan mem-parsing setiap posting ke dalam blok, mencari setiap blok di cache, dan hanya mengirim blok yang tidak di-cache ke AI dalam satu permintaan batch. Suntingan glosarium dan perubahan preset Kepatuhan secara otomatis membatalkan cache terjemahan yang terpengaruh. Lihat statistik dan bersihkan cache di bawah Pemeliharaan.','Enable block-level translation cache reuse across posts'=>'Aktifkan penggunaan kembali cache terjemahan tingkat blok di seluruh posting','Currently skipped for posts that use block-comment attribute placeholders (wp:details summary fields, etc.) — they fall through to the existing single-call translation path.'=>'Saat ini dilewati untuk posting yang menggunakan placeholder atribut komentar blok (wp:details bidang ringkasan, dll.) — mereka akan melewati jalur terjemahan panggilan tunggal yang ada.','General'=>'Umum','Light'=>'Ringan','Meta Description, Excerpt Generator'=>'Meta Deskripsi, Generator Kutipan','Quality'=>'Kualitas','Translation, Content Generator'=>'Terjemahan, Pembuat Konten','Active Provider'=>'Penyedia Aktif','Currently inherited from the %s constant. Selecting a value here will override it.'=>'Saat ini diwarisi dari konstanta %s. Memilih nilai di sini akan mengesampinginya.','Models'=>'Model','Features are grouped into two tiers. Enter the exact model identifier for each tier and provider. Leave a field blank to use the built-in default (shown as placeholder). Only the active provider\'s models are called at runtime — configure the others in advance if you plan to switch.'=>'Fitur dikelompokkan menjadi dua tingkat. Masukkan pengenal model yang tepat untuk setiap tingkat dan penyedia. Tinggalkan bidang kosong untuk menggunakan default bawaan (ditampilkan sebagai placeholder). Hanya model dari penyedia aktif yang dipanggil saat runtime — konfigurasikan yang lain sebelumnya jika Anda berencana beralih.','active'=>'aktif','overridden'=>'yang diubah','Tip: to reset a model to the built-in default, clear the field and save.'=>'Tip: untuk mengatur ulang model ke default bawaan, hapus isian dan simpan.','Glossary'=>'Glosarium','User-managed terminology table per language pair. Entries are appended to the translation system prompt so the AI uses preferred terms consistently — critical for domain vocabulary ("kWp", "PPA", "interconnection point"), brand names that must not translate, and standardised regulatory phrasing. Both language fields are optional: leave "Source language" blank to apply the entry regardless of which language you are translating from; leave "Target language" blank to apply it to all target languages at once.'=>'Tabel terminologi yang dikelola pengguna per pasangan bahasa. Entri ditambahkan ke prompt sistem terjemahan agar AI menggunakan istilah yang disukai secara konsisten — penting untuk kosakata domain ("kWp", "PPA", "titik interkoneksi"), nama merek yang tidak boleh diterjemahkan, dan frasa regulasi yang distandarisasi. Kedua bidang bahasa bersifat opsional: tinggalkan "Bahasa sumber" kosong untuk menerapkan entri tanpa memandang bahasa asal; tinggalkan "Bahasa target" kosong untuk menerapkannya ke semua bahasa target sekaligus.','Glossary entry added.'=>'Entri glosarium ditambahkan.','Glossary entry removed.'=>'Entri glosarium dihapus.','Could not add entry: source term and target term are required.'=>'Tidak dapat menambahkan entri: istilah sumber dan istilah target diperlukan.','Could not save the glossary entry.'=>'Tidak dapat menyimpan entri glosarium.','Source language'=>'Bahasa sumber','— Any —'=>'— Apa saja —','Target language'=>'Bahasa target','— Any target —'=>'— Target apa saja —','Filter'=>'Filter','Reset'=>'Reset','No glossary entries match the current filter. Clear the filter to see all entries, or add a new entry below.'=>'Tidak ada entri glosarium yang cocok dengan filter saat ini. Bersihkan filter untuk melihat semua entri, atau tambahkan entri baru di bawah.','No glossary entries yet. Add one below to start enforcing terminology in translations.'=>'Belum ada entri glosarium. Tambahkan di bawah untuk mulai menegakkan terminologi dalam terjemahan.','Source term'=>'Istilah sumber','Target term'=>'Istilah target','Source lang'=>'Bahasa sumber','Target lang'=>'Bahasa target','Notes'=>'Catatan','any'=>'apa saja','Delete this glossary entry?'=>'Hapus entri glosarium ini?','Delete'=>'Hapus','Add new entry'=>'Tambah entri baru','The phrase as it appears in the source text.'=>'Frasa seperti yang muncul dalam teks sumber.','How it should appear in the translation. Type the same value as the source term to instruct the AI to preserve it verbatim.'=>'Bagaimana seharusnya muncul dalam terjemahan. Ketik nilai yang sama dengan istilah sumber untuk menginstruksikan AI agar mempertahankannya secara verbatim.','— Any source language —'=>'— Sumber apa saja —','Leave blank for brand names and language-agnostic terms that should be enforced regardless of which language we are translating from.'=>'Biarkan kosong untuk nama merek dan istilah yang tidak bergantung bahasa yang harus ditegakkan terlepas dari bahasa apa yang kita terjemahkan.','— Any target language —'=>'— Bahasa target apa saja —','Leave blank to apply this entry to all target languages — ideal for brand names, abbreviations, and terms that must be preserved verbatim in every translation.'=>'Biarkan kosong untuk menerapkan entri ini ke semua bahasa target — ideal untuk nama merek, singkatan, dan istilah yang harus dipertahankan secara verbatim dalam setiap terjemahan.','Optional context for editors (e.g. "ASIC = Application-Specific Integrated Circuit; preserve in English in technical contexts").'=>'Konteks opsional untuk editor (misalnya "ASIC = Sirkuit Terintegrasi Khusus Aplikasi; pertahankan dalam bahasa Inggris dalam konteks teknis").','Add entry'=>'Tambah entri','Limits'=>'Batasan','Authors and above (edit_published_posts)'=>'Penulis dan di atasnya (edit_published_posts)','Contributors and above — default (edit_posts)'=>'Kontributor dan di atasnya — default (edit_posts)','Editors and above (edit_others_posts)'=>'Editor dan di atasnya (edit_others_posts)','Administrators only (manage_options)'=>'Hanya administrator (manage_options)','AI Limits & Security'=>'Batas & Keamanan AI','Cap how much AI usage the site can generate and restrict which user roles may trigger paid AI calls. Sits on top of the per-user rate limit (30 requests / minute, hardcoded) that already protects against single-user runaway loops.'=>'Batasi penggunaan AI yang dapat dihasilkan situs dan batasi peran pengguna yang dapat memicu panggilan AI berbayar. Terletak di atas batas laju per pengguna (30 permintaan / menit, dikodekan keras) yang sudah melindungi terhadap loop liar pengguna tunggal.','Daily request limit'=>'Batas permintaan harian','Site-wide ceiling on AI requests per UTC day (counts both Toolbar translations and block revisions). Counter resets at UTC midnight. Set to 0 to disable the cap.'=>'Batas atas permintaan AI di seluruh situs per hari UTC (menghitung terjemahan Toolbar dan revisi blok). Penghitung direset pada tengah malam UTC. Atur ke 0 untuk menonaktifkan batas.','Minimum role'=>'Peran minimum','Lowest WordPress capability allowed to trigger AI features. Tightening this on multi-author sites prevents Contributors or trial accounts from running paid AI calls. Override per-feature via the linguaforge_required_capability filter.'=>'Kemampuan WordPress terendah yang diizinkan untuk memicu fitur AI. Memperketat ini di situs multi-penulis mencegah Kontributor atau akun percobaan menjalankan panggilan AI berbayar. Override per fitur melalui filter linguaforge_required_capability.','Translation Limits'=>'Batasan Terjemahan','Control how much content is sent to the AI and how large the response can be. Leave a field blank to use the built-in default (shown as placeholder). Raise these values if large pages are being cut off; lower them to reduce API costs.'=>'Kontrol berapa banyak konten yang dikirim ke AI dan seberapa besar respons yang dapat diberikan. Tinggalkan bidang kosong untuk menggunakan default bawaan (ditampilkan sebagai placeholder). Tingkatkan nilai ini jika halaman besar terpotong; turunkan untuk mengurangi biaya API.','Model tier'=>'Tingkat model','Quality (default — Sonnet / GPT-4o / Gemini Pro)'=>'Kualitas (default — Sonnet / GPT-4o / Gemini Pro)','Light (fast and cost-effective — Haiku / Flash)'=>'Ringan (cepat dan hemat biaya — Haiku / Flash)','Which model tier to use for full-page translation. Quality uses the model configured in the Models table above and is recommended for accurate, long-form translation. Switch to Light only if speed or cost is the priority and the content is short.'=>'Tingkat model mana yang digunakan untuk terjemahan halaman penuh. Kualitas menggunakan model yang dikonfigurasi dalam tabel Model di atas dan disarankan untuk terjemahan yang akurat dan panjang. Beralih ke Ringan hanya jika kecepatan atau biaya adalah prioritas dan kontennya singkat.','Max output tokens'=>'Token output maksimum','Maximum number of tokens the AI may produce in a single translation response. If a translation is silently cut off at the end, increase this value. Default: 16 000.'=>'Jumlah token maksimum yang dapat diproduksi AI dalam satu respons terjemahan. Jika terjemahan dipotong secara diam-diam di akhir, tingkatkan nilai ini. Default: 16.000.','Max input characters'=>'Karakter input maksimum','Maximum number of characters of post content forwarded to the AI. 0 means no limit — the full content is always sent (recommended). Set a non-zero value only if your provider has a tight context window. A warning is written to the PHP error log whenever the content is trimmed.'=>'Jumlah karakter maksimum dari konten posting yang diteruskan ke AI. 0 berarti tidak ada batas — seluruh konten selalu dikirim (disarankan). Tetapkan nilai non-nol hanya jika penyedia Anda memiliki jendela konteks yang ketat. Peringatan akan ditulis ke log kesalahan PHP setiap kali konten dipangkas.','Quick Translation'=>'Terjemahan Cepat','Quick Translation is used for snippet/chunk mode — short passages translated on demand from the toolbar, editor, or block popovers. It uses a separate, lighter configuration from the full-page translation to keep responses fast and cost-effective.'=>'Terjemahan Cepat digunakan untuk mode potongan/fragmen — potongan pendek diterjemahkan sesuai permintaan dari toolbar, editor, atau popover blok. Menggunakan konfigurasi yang terpisah dan lebih ringan dari terjemahan halaman penuh untuk menjaga respons tetap cepat dan hemat biaya.','Light (default — fast and cost-effective)'=>'Ringan (default — cepat dan hemat biaya)','Quality (Sonnet / GPT-4o / Gemini Pro)'=>'Kualitas (Soneta / GPT-4o / Gemini Pro)','The Light tier uses the fast model configured in the Models table above (default: Haiku / Flash). Switch to Quality if you need the same translation accuracy as full-page mode for snippets.'=>'Tier Light menggunakan model cepat yang dikonfigurasi dalam tabel Model di atas (default: Haiku / Flash). Beralih ke Kualitas jika Anda membutuhkan tingkat akurasi terjemahan yang sama seperti mode halaman penuh untuk potongan.','Maximum tokens the AI may produce per quick translation. Default: 2 000.'=>'Token maksimum yang dapat diproduksi AI per terjemahan cepat. Default: 2.000.','Maximum characters accepted from the input field. Default: 8 000.'=>'Jumlah karakter maksimum yang diterima dari bidang input. Default: 8.000.','Content Generator'=>'Generator Konten','Controls the token budget and input limits for the AI Content Generator feature. Leave fields blank to use the built-in defaults.'=>'Mengontrol anggaran token dan batas input untuk fitur Generator Konten AI. Biarkan bidang kosong untuk menggunakan default bawaan.','Maximum tokens the AI may produce per generation run. Raise this if full articles are being cut off. Default: 8 192.'=>'Token maksimum yang dapat diproduksi AI per jalannya generasi. Tingkatkan ini jika artikel lengkap terpotong. Default: 8.192.','Max hints characters'=>'Jumlah karakter petunjuk maksimum','Maximum characters read from the Hints field. Default: 2 000.'=>'Jumlah karakter maksimum yang dibaca dari bidang Petunjuk. Default: 2.000.','Max context characters'=>'Jumlah karakter konteks maksimum','Maximum characters of existing post content passed to the AI as seed context when no Hints are provided. Default: 6 000.'=>'Jumlah karakter konten posting yang ada yang diteruskan ke AI sebagai konteks benih saat tidak ada Petunjuk yang disediakan. Default: 6.000.','Maintenance'=>'Pemeliharaan','Language Overrides'=>'Penyesuaian Bahasa','Upload compiled .mo files to override third-party plugin strings for specific locales — for example, a custom VikBooking translation that uses "apartment" instead of "room". Files must follow the WordPress naming convention: {textdomain}-{locale}.mo (e.g. vikbooking-ca.mo). They are stored in the uploads folder and survive plugin updates.'=>'Unggah file .mo yang dikompilasi untuk menimpa string plugin pihak ketiga untuk lokal tertentu — misalnya, terjemahan VikBooking khusus yang menggunakan "apartemen" alih-alih "kamar". File harus mengikuti konvensi penamaan WordPress: {textdomain}-{locale}.mo (misalnya vikbooking-ca.mo). Mereka disimpan di folder unggahan dan tetap ada setelah pembaruan plugin.','Override file uploaded successfully.'=>'File penimpa berhasil diunggah.','Override file deleted.'=>'File penimpa dihapus.','No file was selected.'=>'Tidak ada file yang dipilih.','Only .mo files are accepted.'=>'Hanya file .mo yang diterima.','The upload failed — please try again.'=>'Unggahan gagal — silakan coba lagi.','Could not save the file. Check that the uploads folder is writable.'=>'Tidak dapat menyimpan file. Periksa apakah folder unggahan dapat ditulis.','Invalid filename.'=>'Nama file tidak valid.','Security check failed — file path is not permitted.'=>'Gagal pemeriksaan keamanan — jalur file tidak diizinkan.','An unknown error occurred.'=>'Terjadi kesalahan yang tidak diketahui.','Text domain / locale'=>'Domain teks / lokal','Files'=>'File','Size'=>'Ukuran','Delete all files for this override (both .mo and .po)?'=>'Hapus semua file untuk penimpa ini (baik .mo maupun .po)?','No override files uploaded yet.'=>'Belum ada file penimpa yang diunggah.','Upload .mo file'=>'Unggah file .mo','Accepts compiled .mo files only. Filename must follow the pattern {textdomain}-{locale}.mo. Uploading a file with the same name as an existing one will replace it.'=>'Hanya menerima file .mo yang dikompilasi. Nama file harus mengikuti pola {textdomain}-{locale}.mo. Mengunggah file dengan nama yang sama dengan yang sudah ada akan menggantinya.','Upload Override'=>'Unggah Penimpa','Loco Translate — Copy to Safe Storage'=>'Loco Translate — Salin ke Penyimpanan Aman','Loco Translate stores its custom translations in wp-content/languages/loco/ — a location that can be silently wiped by a WP core update, plugin reinstall, or if Loco Translate itself is removed. Copying files here moves them into the Lingua Forge i18n-overrides directory, which persists through all of those events and is loaded automatically on every request.'=>'Loco Translate menyimpan terjemahan khususnya di wp-content/languages/loco/ — lokasi yang dapat dihapus secara diam-diam oleh pembaruan inti WP, pemasangan ulang plugin, atau jika Loco Translate sendiri dihapus. Menyalin file di sini memindahkan mereka ke direktori Lingua Forge i18n-overrides, yang tetap ada melalui semua kejadian tersebut dan dimuat secara otomatis setiap permintaan.','File copied to safe storage successfully.'=>'File berhasil disalin ke penyimpanan aman.','Source file not found.'=>'File sumber tidak ditemukan.','Could not copy the file. Check that the uploads folder is writable.'=>'Tidak dapat menyalin file. Periksa apakah folder unggahan dapat ditulis.','Invalid file reference.'=>'Referensi file tidak valid.','Type'=>'Jenis','✓ In safe storage'=>'✓ Disimpan di penyimpanan aman','Copy to safe storage'=>'Salin ke penyimpanan aman','No custom Loco Translate files found yet. They appear here once you save a translation in Loco Translate.'=>'Belum ada file Loco Translate khusus yang ditemukan. Mereka akan muncul di sini setelah Anda menyimpan terjemahan di Loco Translate.','AI Cache'=>'Cache AI','Lingua Forge caches AI-generated translations, meta descriptions, excerpts, and generated content per-post so unchanged inputs do not re-trigger a paid API call. Cached entries are automatically invalidated when their inputs change. Clear the cache manually to reclaim database space, force a resync after switching providers or editing prompt templates, or troubleshoot a cache-related issue.'=>'Lingua Forge menyimpan cache terjemahan yang dihasilkan AI, deskripsi meta, kutipan, dan konten yang dihasilkan per-pos sehingga input yang tidak berubah tidak memicu panggilan API berbayar. Entri cache secara otomatis tidak berlaku saat input mereka berubah. Bersihkan cache secara manual untuk mengembalikan ruang basis data, paksa sinkronisasi ulang setelah beralih penyedia atau mengedit template prompt, atau memecahkan masalah terkait cache.','AI cache cleared. %d entry was removed.'=>'Cache AI dibersihkan. %d entri dihapus.' . "\0" . '','Clear all cached AI results? Future requests will trigger fresh API calls until the cache rebuilds.'=>'Bersihkan semua hasil AI yang di-cache? Permintaan di masa depan akan memicu panggilan API baru sampai cache dibangun kembali.','Clear AI Cache'=>'Bersihkan Cache AI','Debug Files'=>'File Debug','When debug logging is enabled (via the toggle below or by defining LINGUAFORGE_AI_DEBUG in wp-config.php), the Translation and FSE template translation features write their raw AI prompts and responses to disk for troubleshooting. Use this section to monitor that output and clear it once you have what you need — the files can grow quickly on large pages. Configure the destination directory via the linguaforge_debug_dir filter.'=>'Ketika pencatatan debug diaktifkan (melalui toggle di bawah atau dengan mendefinisikan LINGUAFORGE_AI_DEBUG di wp-config.php), fitur terjemahan dan template FSE menulis prompt AI mentah dan responsnya ke disk untuk pemecahan masalah. Gunakan bagian ini untuk memantau output tersebut dan bersihkan setelah Anda mendapatkan apa yang Anda butuhkan — file dapat tumbuh dengan cepat di halaman besar. Konfigurasikan direktori tujuan melalui filter linguaforge_debug_dir.','Debug files cleared. %d file was removed.'=>'File debug dibersihkan. %d file dihapus.' . "\0" . '','Debug logging enabled.'=>'Pencatatan debug diaktifkan.','Debug logging disabled.'=>'Pencatatan debug dinonaktifkan.','Debug logging'=>'Pencatatan debug','Write AI prompts and responses to disk for troubleshooting'=>'Tulis prompt AI dan respons ke disk untuk pemecahan masalah','Forced ON by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Dipaksa ON oleh konstanta LINGUAFORGE_AI_DEBUG di wp-config.php. Hapus baris itu untuk mengontrol toggle ini dari sini.','Forced OFF by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Dipaksa OFF oleh konstanta LINGUAFORGE_AI_DEBUG di wp-config.php. Hapus baris itu untuk mengontrol toggle ini dari sini.','Files land in the directory below. Useful for diagnosing translation issues — turn off once you have what you need so the files do not accumulate. You can also force this from wp-config.php with `define( \'LINGUAFORGE_AI_DEBUG\', true );` which overrides the toggle.'=>'File disimpan di direktori di bawah ini. Berguna untuk mendiagnosis masalah terjemahan — matikan setelah Anda mendapatkan apa yang Anda butuhkan agar file tidak menumpuk. Anda juga dapat memaksa ini dari wp-config.php dengan `define( \'LINGUAFORGE_AI_DEBUG\', true );` yang akan menimpa toggle.','Currently:'=>'Saat ini:','✓ Enabled'=>'✓ Diaktifkan','✗ Disabled'=>'✗ Dinonaktifkan','Directory'=>'Direktori','Filter with linguaforge_debug_dir to redirect debug output to a non-public location.'=>'Filter dengan linguaforge_debug_dir untuk mengarahkan output debug ke lokasi yang tidak publik.','.txt file(s) in the directory'=>'.txt file(s) di direktori','Save Debug Setting'=>'Simpan Pengaturan Debug','Delete all .txt files in the debug directory? The directory itself will remain so future debug writes still land cleanly.'=>'Hapus semua file .txt di direktori debug? Direktori itu sendiri akan tetap ada sehingga penulisan debug di masa depan tetap bersih.','Clear Debug Files'=>'Hapus File Debug','Per-block translation cache shared across posts. Configure on/off in Settings → Behavior. Stats below show what is currently cached; clearing forces every block to be re-translated on next request (useful after upgrading models or to recover database space).'=>'Cache terjemahan per-blok yang dibagikan di seluruh posting. Konfigurasi aktif/nonaktif di Pengaturan → Perilaku. Statistik di bawah menunjukkan apa yang saat ini di-cache; menghapus memaksa setiap blok untuk diterjemahkan ulang pada permintaan berikutnya (berguna setelah memperbarui model atau untuk memulihkan ruang basis data).','Translation Memory cleared. %d cached block was removed.'=>'Memori Terjemahan dibersihkan. %d blok yang di-cache dihapus.' . "\0" . '','Status'=>'Status','— toggle in Settings → Behavior.'=>'— toggle di Pengaturan → Perilaku.','Cached blocks'=>'Blok yang di-cache','Cumulative cache hits'=>'Jumlah total keberhasilan cache','(avg %.1f hits/block)'=>'(rata-rata %.1f keberhasilan/blok)','Oldest entry'=>'Entri tertua','Newest entry'=>'Entri terbaru','Approximate size'=>'Ukuran perkiraan','Clear the entire Translation Memory? Future translations will rebuild the cache as they run.'=>'Hapus seluruh Memori Terjemahan? Terjemahan di masa depan akan membangun kembali cache saat mereka berjalan.','Clear Translation Memory'=>'Hapus Memori Terjemahan','Uninstall Behaviour'=>'Penghapusan Perilaku','Controls what happens when an administrator deletes the plugin from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments and translation relationships are kept by default so an accidental uninstall or a reinstall can pick up where it left off.'=>'Mengontrol apa yang terjadi ketika administrator menghapus plugin dari Plugins → Installed Plugins → Delete. Pengaturan plugin dan cache AI selalu dihapus. Penugasan bahasa dan hubungan terjemahan secara default dipertahankan sehingga penghapusan tidak sengaja atau pemasangan ulang dapat melanjutkan dari tempat terakhir.','Uninstall setting saved.'=>'Pengaturan penghapusan disimpan.','Delete content data on uninstall'=>'Hapus data konten saat uninstall','Also delete language assignments, translation relationships, meta descriptions, glossary, and Translation Memory when the plugin is uninstalled'=>'Juga hapus penugasan bahasa, hubungan terjemahan, meta deskripsi, glosarium, dan Memori Terjemahan saat plugin dihapus','Warning:'=>'Peringatan:','If checked, uninstalling the plugin will permanently delete all language assignments, translation relationships, meta descriptions, per-page presets, the AI glossary, and Translation Memory for every post on this site. This cannot be undone. Leave unchecked unless you are fully removing multilingual support from the site.'=>'Jika dicentang, menghapus plugin akan secara permanen menghapus semua penugasan bahasa, hubungan terjemahan, meta deskripsi, preset per halaman, glosarium AI, dan Memori Terjemahan untuk setiap posting di situs ini. Ini tidak dapat dibatalkan. Biarkan tidak dicentang kecuali Anda benar-benar menghapus dukungan multibahasa dari situs.','Save Uninstall Setting'=>'Simpan Pengaturan Uninstall','Router'=>'Router','Primary language saved.'=>'Bahasa utama disimpan.','Permalink rules flushed successfully.'=>'Aturan permalink berhasil dibersihkan.','Primary Language'=>'Bahasa Utama','The primary language is always served at the root of your site — no URL prefix in path mode, no language subdomain in subdomain mode. All other languages use either a /lang/ path prefix (e.g. example.com/de/) or a language subdomain (e.g. de.example.com), depending on the URL structure setting below.'=>'Bahasa utama selalu disajikan di akar situs Anda — tanpa prefix URL dalam mode path, tanpa subdomain bahasa dalam mode subdomain. Semua bahasa lain menggunakan prefix path /lang/ (misalnya example.com/de/) atau subdomain bahasa (misalnya de.example.com), tergantung pengaturan struktur URL di bawah.','Primary language'=>'Bahasa utama','After changing the primary language, flush permalinks (section below) for the URL routing to update.'=>'Setelah mengubah bahasa utama, bersihkan permalink (bagian di bawah) agar pengaturan URL diperbarui.','URL structure'=>'Struktur URL','Path prefix — example.com/de/'=>'Prefix path — example.com/de/','Subdomain — de.example.com/'=>'Subdomain — de.example.com/','Subdomain mode requires your web server to point all language subdomains (e.g. de.example.com) to this WordPress installation. After switching modes, flush permalink rules and clear any caches. If your home URL includes www (e.g. www.example.com), use the lf_base_domain filter to set the bare apex domain so subdomains are constructed correctly.'=>'Mode subdomain memerlukan server web Anda untuk menunjuk semua subdomain bahasa (misalnya de.example.com) ke instalasi WordPress ini. Setelah beralih mode, bersihkan aturan permalink dan hapus cache apa pun. Jika URL beranda Anda menyertakan www (misalnya www.example.com), gunakan filter lf_base_domain untuk mengatur domain puncak agar subdomain dibangun dengan benar.','Browser language redirect'=>'Pengalihan bahasa browser','Redirect visitors to their preferred language based on the browser\'s Accept-Language header'=>'Alihkan pengunjung ke bahasa pilihan mereka berdasarkan header Accept-Language browser','When enabled, first-time visitors with no language cookie and no language prefix in the URL are redirected to the closest matching language version. The redirect is skipped if the browser\'s preferred language is not among the active router languages. Once a visitor selects a language via the switcher, the cookie takes priority and the browser header is ignored on all future visits.'=>'Jika diaktifkan, pengunjung pertama kali yang tidak memiliki cookie bahasa dan tidak memiliki prefix bahasa di URL akan dialihkan ke versi bahasa yang paling cocok. Pengalihan dilewati jika bahasa yang dipilih browser tidak termasuk dalam bahasa router aktif. Setelah pengunjung memilih bahasa melalui switcher, cookie menjadi prioritas dan header browser diabaikan pada kunjungan berikutnya.','Save Router Settings'=>'Simpan Pengaturan Router','Flush Permalinks'=>'Flush Permalinks','Regenerates WordPress rewrite rules so URL prefixes, language-specific slugs, and archive rewrites are all in sync. Necessary after changing the primary language or adding new language support.'=>'Mengregenerasi ulang aturan penulisan ulang WordPress sehingga prefiks URL, slug khusus bahasa, dan penulisan ulang arsip semuanya sinkron. Diperlukan setelah mengubah bahasa utama atau menambahkan dukungan bahasa baru.','Flush Permalink Rules'=>'Flush Permalink Rules','Active Languages'=>'Bahasa Aktif','Languages currently known to the router (derived from installed WordPress locale packs plus the primary language). Install additional language packs in the section below to make more languages available for routing and translation.'=>'Bahasa yang saat ini dikenal oleh router (berasal dari paket lokal WordPress yang terpasang plus bahasa utama). Pasang paket bahasa tambahan di bagian di bawah ini agar lebih banyak bahasa tersedia untuk routing dan terjemahan.','%d locale pack installed.'=>'%d paket lokal terpasang.' . "\0" . '','Install a Language'=>'Pasang Bahasa','Download and install a WordPress core language pack directly from WordPress.org. Once installed, the locale becomes available for URL routing and the AI translation workflow. The list of available languages is fetched on demand — click the button below to load it.'=>'Unduh dan pasang paket bahasa inti WordPress langsung dari WordPress.org. Setelah terpasang, locale menjadi tersedia untuk routing URL dan alur kerja terjemahan AI. Daftar bahasa yang tersedia diambil sesuai permintaan — klik tombol di bawah untuk memuatnya.','Language installation is disabled on this server. The DISALLOW_FILE_MODS constant is set in wp-config.php. Install language packs manually via WP-CLI: wp language core install de_DE'=>'Pemasangan bahasa dinonaktifkan di server ini. Konstanta DISALLOW_FILE_MODS diatur di wp-config.php. Pasang paket bahasa secara manual melalui WP-CLI: wp language core install de_DE','Load available languages'=>'Muat bahasa yang tersedia','— select a language —'=>'— pilih bahasa —','Install'=>'Pasang','Language Setup'=>'Pengaturan Bahasa','No secondary languages configured. Install a language pack above to enable template scaffolding.'=>'Tidak ada bahasa sekunder yang dikonfigurasi. Pasang paket bahasa di atas untuk mengaktifkan kerangka template.','Select a language to manage its FSE templates, template parts, and navigation menus.'=>'Pilih bahasa untuk mengelola template FSE, bagian template, dan menu navigasi.','Forbidden'=>'Dilarang','Language installation is disabled on this server (DISALLOW_FILE_MODS is set).'=>'Pemasangan bahasa dinonaktifkan di server ini (DISALLOW_FILE_MODS diatur).','Invalid locale code.'=>'Kode locale tidak valid.','Language %s installed successfully.'=>'Bahasa %s berhasil dipasang.','Language pack installation failed. The language may already be installed, the locale code may be incorrect, or your server may block file writes.'=>'Gagal memasang paket bahasa. Bahasa mungkin sudah terpasang, kode locale mungkin salah, atau server Anda memblokir penulisan file.','Navigations'=>'Navigasi','Navigation translation requires an active AI provider. Configure an API key in the API Keys tab.'=>'Terjemahan navigasi memerlukan penyedia AI aktif. Konfigurasikan kunci API di tab Kunci API.','Navigation'=>'Navigasi','Action'=>'Tindakan','Re-translate'=>'Terjemahkan ulang','CPT Block Patterns'=>'Polanya Blok CPT','Block patterns registered for custom post types. Use the Translate button to produce a language variant. The translated content is saved here and can be copied into any CPT post from the block editor Pattern inserter or used as a starting point for a Synced Pattern (Reusable Block).'=>'Polanya terdaftar untuk tipe pos khusus. Gunakan tombol Terjemahkan untuk menghasilkan varian bahasa. Konten yang diterjemahkan disimpan di sini dan dapat disalin ke pos CPT apa pun dari penyisip pola editor blok atau digunakan sebagai titik awal untuk Pola Sinkron (Blok yang Dapat Digunakan Kembali).','Pattern'=>'Pola','Post Types'=>'Tipe Pos','✓ Translation saved'=>'✓ Terjemahan disimpan','View'=>'Lihat','Template Parts'=>'Bagian Template','Language-specific copies of the theme\'s template parts. Once scaffolded, templates are updated to reference the language-specific part.'=>'Salinan khusus bahasa dari bagian template tema. Setelah dibuat, template diperbarui untuk merujuk ke bagian khusus bahasa.','Part'=>'Bagian','Status / Actions'=>'Status / Tindakan','Fix Links'=>'Perbaiki Tautan','Fix Nav'=>'Perbaiki Navigasi','Create'=>'Buat','Templates'=>'Template','FSE templates seeded from the active theme. Create then customise in the Site Editor.'=>'Template FSE disemai dari tema aktif. Buat lalu sesuaikan di Editor Situs.','Actions'=>'Tindakan','Fix Parts'=>'Perbaiki Bagian','Create missing'=>'Buat yang hilang','Translate all'=>'Terjemahkan semua','Fix all parts'=>'Perbaiki semua bagian','Fix all links'=>'Perbaiki semua tautan','Anthropic (Claude)'=>'Anthropic (Claude)','OpenAI (GPT)'=>'OpenAI (GPT)','Google (Gemini)'=>'Google (Gemini)','Testing…'=>'Sedang pengujian…','✓ Connection OK'=>'✓ Koneksi OK','✗ Failed:'=>'✗ Gagal:','No response from provider — check the error log for details.'=>'Tidak ada respons dari penyedia — periksa log error untuk detailnya.','Network error — could not reach the WordPress AJAX endpoint.'=>'Kesalahan jaringan — tidak dapat menghubungi endpoint AJAX WordPress.','Loading…'=>'Memuat…','Installing…'=>'Menginstal…','✓ Language installed.'=>'✓ Bahasa terinstal.','✗ Error:'=>'✗ Kesalahan:','Creating…'=>'Sedang membuat…','✓ All templates created.'=>'✓ Semua template dibuat.','Some templates could not be created.'=>'Beberapa template tidak dapat dibuat.','✓ All parts created.'=>'✓ Semua bagian dibuat.','Some parts could not be created.'=>'Beberapa bagian tidak dapat dibuat.','✓ All translated.'=>'✓ Semuanya diterjemahkan.','Some translations failed.'=>'Beberapa terjemahan gagal.','Review carefully — links and slugs not updated.'=>'Periksa dengan cermat — tautan dan slug tidak diperbarui.','Fixing…'=>'Memperbaiki…','✓ Links fixed.'=>'✓ Tautan diperbaiki.','Some link fixes failed.'=>'Beberapa perbaikan tautan gagal.','✓ Parts fixed.'=>'✓ Bagian diperbaiki.','Some part fixes failed.'=>'Beberapa perbaikan bagian gagal.','✓ Nav refs fixed.'=>'✓ Referensi navigasi diperbaiki.','Some nav ref fixes failed.'=>'Beberapa perbaikan referensi navigasi gagal.','✓ Pattern translated.'=>'✓ Pola diterjemahkan.','Pattern translation failed.'=>'Gagal menerjemahkan pola.','Hide'=>'Sembunyikan','Built-in preset instructions:'=>'Instruksi preset bawaan:','No built-in instructions — each AI feature uses its own tuned defaults. Fill in the Custom prompt instructions field below to add your own site-wide rules.'=>'Tidak ada instruksi bawaan — setiap fitur AI menggunakan default yang disesuaikan sendiri. Isi bidang instruksi Kustom di bawah ini untuk menambahkan aturan situs Anda sendiri.','Settings'=>'Pengaturan','You do not have permission to manage these settings.'=>'Anda tidak memiliki izin untuk mengelola pengaturan ini.','Lingua Forge — Settings'=>'Lingua Forge — Pengaturan','Settings saved.'=>'Pengaturan disimpan.','Save Settings'=>'Simpan Pengaturan','Sta